INSERT INTO translations (key, value, locale) VALUES
  ('authPasskeySetupAndroidBody', 'Passkeys on Android need a screen lock such as a PIN, pattern, password, fingerprint, or face unlock. Set one up in your device security settings, then try again.', 'en'),
  ('authPasskeySetupAndroidButton', 'Open screen lock settings', 'en'),
  ('authPasskeySetupAndroidInstructionsBody', 'Open Settings, then Security & privacy (the name can vary by device) and set up a screen lock. Passkeys may also require Google Password Manager to be enabled.', 'en'),
  ('authPasskeySetupAndroidInstructionsTitle', 'Set up a screen lock for passkeys', 'en'),
  ('authPasskeySetupAndroidTitle', 'Set up passkeys on this Android device', 'en'),
  ('authPasskeySetupIosBody', 'Passkeys on iPhone use your device passcode and iCloud Passwords & Keychain. Turn on these features in Settings, then try again.', 'en'),
  ('authPasskeySetupIosButton', 'View iPhone setup steps', 'en'),
  ('authPasskeySetupIosInstructionsBody', E'1. In Settings, set a passcode under Face ID & Passcode or Touch ID & Passcode.\n\n2. Tap your name, then iCloud > Passwords & Keychain, and turn on Sync this iPhone.\n\nMenu names can vary slightly by iOS version. After setup, return here and try the passkey again.', 'en'),
  ('authPasskeySetupIosInstructionsTitle', 'Set up passkeys on iPhone', 'en'),
  ('authPasskeySetupIosTitle', 'Set up passkeys on this iPhone', 'en'),
  ('authPasskeySetupMacBody', 'Passkeys on Mac use Touch ID or your Mac login password and may sync through iCloud Passwords & Keychain. Use the setup steps for your Mac.', 'en'),
  ('authPasskeySetupMacButton', 'View Mac setup steps', 'en'),
  ('authPasskeySetupMacInstructionsBody', 'In System Settings, check Touch ID or your login password, then open your Apple Account > iCloud > Passwords & Keychain and enable syncing. Menu names vary by macOS version.', 'en'),
  ('authPasskeySetupMacInstructionsTitle', 'Set up passkeys on Mac', 'en'),
  ('authPasskeySetupMacTitle', 'Set up passkeys on this Mac', 'en'),
  ('authPasskeySetupOtherBody', 'This device does not currently report a ready platform authenticator. Check the device or browser security settings for passkey, screen-lock, or biometric setup.', 'en'),
  ('authPasskeySetupOtherButton', 'View setup steps', 'en'),
  ('authPasskeySetupOtherInstructionsBody', 'Passkey setup depends on your device and browser. Enable a device screen lock or biometric unlock, and make sure a passkey provider is available. You can also use a passkey saved on another device.', 'en'),
  ('authPasskeySetupOtherInstructionsTitle', 'Set up passkeys on this device', 'en'),
  ('authPasskeySetupOtherTitle', 'Set up passkeys on this device', 'en'),
  ('authPasskeySetupWindowsBody', 'Passkeys on Windows use Windows Hello. Set up a PIN, fingerprint, or face sign-in in Windows Settings, then try again.', 'en'),
  ('authPasskeySetupWindowsButton', 'Open Windows Hello settings', 'en'),
  ('authPasskeySetupWindowsInstructionsBody', 'Open Settings > Accounts > Sign-in options, then set up a Windows Hello PIN, fingerprint, or face sign-in. Return here and try the passkey again.', 'en'),
  ('authPasskeySetupWindowsInstructionsTitle', 'Set up Windows Hello for passkeys', 'en'),
  ('authPasskeySetupWindowsTitle', 'Set up passkeys on this PC', 'en')
INSERT INTO translations (key, value, locale) VALUES
  ('authPasskeySetupAndroidBody', 'Las llaves de acceso en Android requieren un bloqueo de pantalla, como un PIN, patrón, contraseña, huella dactilar o reconocimiento facial. Configúralo en los ajustes de seguridad del dispositivo e inténtalo de nuevo.', 'es'),
  ('authPasskeySetupAndroidButton', 'Abrir ajustes de bloqueo de pantalla', 'es'),
  ('authPasskeySetupAndroidInstructionsBody', 'Abre Ajustes y luego Seguridad y privacidad (el nombre puede variar según el dispositivo) para configurar un bloqueo de pantalla. También puede ser necesario activar el Gestor de contraseñas de Google.', 'es'),
  ('authPasskeySetupAndroidInstructionsTitle', 'Configura un bloqueo de pantalla para las llaves de acceso', 'es'),
  ('authPasskeySetupAndroidTitle', 'Configura las llaves de acceso en este dispositivo Android', 'es'),
  ('authPasskeySetupIosBody', 'Las llaves de acceso en iPhone usan el código del dispositivo y Contraseñas y Llavero de iCloud. Activa estas funciones en Ajustes e inténtalo de nuevo.', 'es'),
  ('authPasskeySetupIosButton', 'Ver los pasos de configuración del iPhone', 'es'),
  ('authPasskeySetupIosInstructionsBody', E'1. En Ajustes, configura un código en Face ID y código o Touch ID y código.\n\n2. Toca tu nombre y luego iCloud > Contraseñas y Llavero; activa Sincronizar este iPhone.\n\nLos nombres de los menús pueden variar según la versión de iOS. Después, vuelve aquí e inténtalo de nuevo.', 'es'),
  ('authPasskeySetupIosInstructionsTitle', 'Configura las llaves de acceso en el iPhone', 'es'),
  ('authPasskeySetupIosTitle', 'Configura las llaves de acceso en este iPhone', 'es'),
  ('authPasskeySetupMacBody', 'Las llaves de acceso en Mac usan Touch ID o la contraseña de inicio de sesión del Mac y pueden sincronizarse mediante Contraseñas y Llavero de iCloud. Sigue los pasos de configuración del Mac.', 'es'),
  ('authPasskeySetupMacButton', 'Ver los pasos de configuración del Mac', 'es'),
  ('authPasskeySetupMacInstructionsBody', 'En Ajustes del Sistema, comprueba Touch ID o la contraseña de inicio de sesión. Después, abre tu Cuenta de Apple > iCloud > Contraseñas y Llavero y activa la sincronización. Los nombres pueden variar según la versión de macOS.', 'es'),
  ('authPasskeySetupMacInstructionsTitle', 'Configura las llaves de acceso en Mac', 'es'),
  ('authPasskeySetupMacTitle', 'Configura las llaves de acceso en este Mac', 'es'),
  ('authPasskeySetupOtherBody', 'Este dispositivo no indica que haya un autenticador de plataforma listo. Revisa los ajustes de seguridad del dispositivo o del navegador para configurar llaves de acceso, bloqueo de pantalla o datos biométricos.', 'es'),
  ('authPasskeySetupOtherButton', 'Ver los pasos de configuración', 'es'),
  ('authPasskeySetupOtherInstructionsBody', 'La configuración de las llaves de acceso depende del dispositivo y del navegador. Activa un bloqueo de pantalla o el desbloqueo biométrico y comprueba que haya un proveedor de llaves de acceso disponible. También puedes usar una llave guardada en otro dispositivo.', 'es'),
  ('authPasskeySetupOtherInstructionsTitle', 'Configura las llaves de acceso en este dispositivo', 'es'),
  ('authPasskeySetupOtherTitle', 'Configura las llaves de acceso en este dispositivo', 'es'),
  ('authPasskeySetupWindowsBody', 'Las llaves de acceso en Windows usan Windows Hello. Configura un PIN, la huella dactilar o el reconocimiento facial en Configuración de Windows e inténtalo de nuevo.', 'es'),
  ('authPasskeySetupWindowsButton', 'Abrir la configuración de Windows Hello', 'es'),
  ('authPasskeySetupWindowsInstructionsBody', 'Abre Configuración > Cuentas > Opciones de inicio de sesión y configura un PIN, la huella dactilar o el reconocimiento facial de Windows Hello. Después, vuelve aquí e inténtalo de nuevo.', 'es'),
  ('authPasskeySetupWindowsInstructionsTitle', 'Configura Windows Hello para usar llaves de acceso', 'es'),
  ('authPasskeySetupWindowsTitle', 'Configura las llaves de acceso en este PC', 'es')
INSERT INTO translations (key, value, locale) VALUES
  ('authPasskeySetupAndroidBody', 'מפתחות גישה ב-Android דורשים נעילת מסך, כגון קוד PIN, תבנית, סיסמה, טביעת אצבע או זיהוי פנים. יש להגדיר נעילה בהגדרות האבטחה של המכשיר ולנסות שוב.', 'he'),
  ('authPasskeySetupAndroidButton', 'פתיחת הגדרות נעילת המסך', 'he'),
  ('authPasskeySetupAndroidInstructionsBody', 'יש לפתוח את ההגדרות, ואז את אבטחה ופרטיות (השם עשוי להשתנות בין מכשירים), ולהגדיר נעילת מסך. ייתכן שיהיה צורך להפעיל גם את מנהל הסיסמאות של Google.', 'he'),
  ('authPasskeySetupAndroidInstructionsTitle', 'הגדרת נעילת מסך למפתחות גישה', 'he'),
  ('authPasskeySetupAndroidTitle', 'הגדרת מפתחות גישה במכשיר Android הזה', 'he'),
  ('authPasskeySetupIosBody', 'מפתחות גישה ב-iPhone משתמשים בקוד הגישה של המכשיר ובסיסמאות ובצרור המפתחות של iCloud. יש להפעיל את התכונות האלה בהגדרות ולנסות שוב.', 'he'),
  ('authPasskeySetupIosButton', 'הצגת שלבי ההגדרה ל-iPhone', 'he'),
  ('authPasskeySetupIosInstructionsBody', E'1. בהגדרות, יש להגדיר קוד גישה תחת Face ID וקוד גישה או Touch ID וקוד גישה.\n\n2. יש להקיש על השם שלך, ואז iCloud > סיסמאות וצרור מפתחות, ולהפעיל את סנכרון ה-iPhone הזה.\n\nשמות התפריטים עשויים להשתנות מעט בין גרסאות iOS. לאחר ההגדרה, יש לחזור לכאן ולנסות שוב.', 'he'),
  ('authPasskeySetupIosInstructionsTitle', 'הגדרת מפתחות גישה ב-iPhone', 'he'),
  ('authPasskeySetupIosTitle', 'הגדרת מפתחות גישה ב-iPhone הזה', 'he'),
  ('authPasskeySetupMacBody', 'מפתחות גישה ב-Mac משתמשים ב-Touch ID או בסיסמת ההתחברות ל-Mac, וניתן לסנכרן אותם באמצעות סיסמאות וצרור המפתחות של iCloud. יש לפעול לפי שלבי ההגדרה ל-Mac.', 'he'),
  ('authPasskeySetupMacButton', 'הצגת שלבי ההגדרה ל-Mac', 'he'),
  ('authPasskeySetupMacInstructionsBody', 'בהגדרות המערכת, יש לבדוק את Touch ID או את סיסמת ההתחברות. לאחר מכן יש לפתוח את חשבון Apple > iCloud > סיסמאות וצרור מפתחות ולהפעיל סנכרון. שמות התפריטים משתנים לפי גרסת macOS.', 'he'),
  ('authPasskeySetupMacInstructionsTitle', 'הגדרת מפתחות גישה ב-Mac', 'he'),
  ('authPasskeySetupMacTitle', 'הגדרת מפתחות גישה ב-Mac הזה', 'he'),
  ('authPasskeySetupOtherBody', 'המכשיר הזה לא מדווח כרגע על מאמת פלטפורמה מוכן. יש לבדוק בהגדרות האבטחה של המכשיר או הדפדפן כיצד להגדיר מפתחות גישה, נעילת מסך או אימות ביומטרי.', 'he'),
  ('authPasskeySetupOtherButton', 'הצגת שלבי ההגדרה', 'he'),
  ('authPasskeySetupOtherInstructionsBody', 'הגדרת מפתחות גישה תלויה במכשיר ובדפדפן. יש להפעיל נעילת מסך או פתיחה ביומטרית ולוודא שספק מפתחות גישה זמין. אפשר גם להשתמש במפתח גישה שנשמר במכשיר אחר.', 'he'),
  ('authPasskeySetupOtherInstructionsTitle', 'הגדרת מפתחות גישה במכשיר הזה', 'he'),
  ('authPasskeySetupOtherTitle', 'הגדרת מפתחות גישה במכשיר הזה', 'he'),
  ('authPasskeySetupWindowsBody', 'מפתחות גישה ב-Windows משתמשים ב-Windows Hello. יש להגדיר קוד PIN, טביעת אצבע או זיהוי פנים בהגדרות Windows ולנסות שוב.', 'he'),
  ('authPasskeySetupWindowsButton', 'פתיחת הגדרות Windows Hello', 'he'),
  ('authPasskeySetupWindowsInstructionsBody', 'יש לפתוח את הגדרות > חשבונות > אפשרויות כניסה ולהגדיר קוד PIN, טביעת אצבע או זיהוי פנים של Windows Hello. לאחר מכן יש לחזור לכאן ולנסות שוב.', 'he'),
  ('authPasskeySetupWindowsInstructionsTitle', 'הגדרת Windows Hello למפתחות גישה', 'he'),
  ('authPasskeySetupWindowsTitle', 'הגדרת מפתחות גישה במחשב הזה', 'he')
